-- ----------------------------
-- Table structure for mini_bookkeeping_category
-- ----------------------------
DROP TABLE IF EXISTS `mini_bookkeeping_category`;
CREATE TABLE `mini_bookkeeping_category` (
  `id` varchar(36) NOT NULL,
  `name` varchar(50) NOT NULL COMMENT '分类名称',
  `type` enum('income','expense') NOT NULL COMMENT '收入/支出',
  `icon` varchar(100) DEFAULT NULL COMMENT '图标名称或URL',
  `color` varchar(20) DEFAULT '#409eff' COMMENT '颜色',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `is_system` tinyint(1) DEFAULT '0' COMMENT '是否系统分类',
  `user_id` varchar(36) DEFAULT NULL COMMENT '用户ID，系统分类为NULL',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='记账分类表';

-- ----------------------------
-- Records of mini_bookkeeping_category
-- ----------------------------

-- ----------------------------
-- Table structure for mini_bookkeeping_icon
-- ----------------------------
DROP TABLE IF EXISTS `mini_bookkeeping_icon`;
CREATE TABLE `mini_bookkeeping_icon` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL COMMENT '图标名称',
  `icon` varchar(100) NOT NULL COMMENT '图标标识',
  `type` enum('income','expense','common') NOT NULL COMMENT '适用类型',
  `category` varchar(50) DEFAULT NULL COMMENT '图标分类',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_type` (`type`),
  KEY `idx_category` (`category`),
  KEY `idx_type_category` (`type`,`category`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COMMENT='图标库表';

-- ----------------------------
-- Records of mini_bookkeeping_icon
-- ----------------------------

