-- Table structure for mini_bookkeeping_record
-- ----------------------------
DROP TABLE IF EXISTS `mini_bookkeeping_record`;
CREATE TABLE `mini_bookkeeping_record` (
  `id` varchar(36) NOT NULL,
  `user_id` varchar(36) NOT NULL COMMENT '用户ID',
  `category_id` varchar(36) NOT NULL COMMENT '分类ID',
  `type` enum('income','expense') NOT NULL COMMENT '收入/支出',
  `amount` decimal(10,2) NOT NULL COMMENT '金额',
  `title` varchar(100) DEFAULT NULL COMMENT '标题/备注',
  `remark` text COMMENT '详细备注',
  `record_date` date NOT NULL COMMENT '记录日期',
  `record_time` time DEFAULT NULL COMMENT '记录时间',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='记账记录表';

