-- ----------------------------
-- Table structure for platform_permission
-- ----------------------------
DROP TABLE IF EXISTS `platform_permission`;
CREATE TABLE `platform_permission` (
  `id` varchar(20) DEFAULT NULL COMMENT '权限ID',
  `permission_id` int(11) NOT NULL AUTO_INCREMENT,
  `pid` int(11) NOT NULL COMMENT '一级菜单为0,父id',
  `creator_id` int(11) NOT NULL COMMENT '创建人',
  `title` varchar(255) DEFAULT NULL COMMENT '权限名称',
  `name` varchar(255) DEFAULT NULL COMMENT '页面 name',
  `description` varchar(255) DEFAULT NULL COMMENT '权限描述',
  `path` varchar(255) DEFAULT NULL COMMENT '浏览器访问路由',
  `component` varchar(255) DEFAULT NULL COMMENT '页面地址',
  `hide` int(1) DEFAULT '0' COMMENT '是否显示 1隐藏，0显示',
  `order_num` tinyint(1) DEFAULT NULL COMMENT '排序',
  `type` tinyint(1) NOT NULL COMMENT '是否为目录，0-目录，1-菜单 2- 按钮',
  `access` varchar(100) NOT NULL COMMENT '菜单权限标记',
  `icon` varchar(255) DEFAULT NULL COMMENT '图标',
  `status` int(1) NOT NULL DEFAULT '1' COMMENT '是否启用，0 禁用 1 启用',
  `u_time` datetime DEFAULT NULL,
  `c_time` datetime DEFAULT NULL,
  `d_time` datetime DEFAULT NULL,
  `deleted` int(11) NOT NULL DEFAULT '0' COMMENT '1 删除  0 存在',
  PRIMARY KEY (`permission_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10013 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of platform_permission
-- ----------------------------

