-- Table structure for platform_role
-- ----------------------------
DROP TABLE IF EXISTS `platform_role`;
CREATE TABLE `platform_role` (
  `id` int(11) DEFAULT NULL COMMENT '角色ID',
  `role_id` int(11) NOT NULL AUTO_INCREMENT,
  `creator_id` int(11) DEFAULT NULL COMMENT '创建人id',
  `name` varchar(255) NOT NULL COMMENT '角色名称',
  `description` varchar(255) DEFAULT NULL COMMENT '角色描述',
  `c_time` datetime NOT NULL,
  `u_time` datetime NOT NULL,
  `order` int(1) DEFAULT NULL COMMENT '排序',
  `status` int(1) NOT NULL COMMENT '状态， 0 禁用 ，1 启用',
  `label` varchar(255) DEFAULT NULL COMMENT '国际化名称',
  `d_time` datetime DEFAULT NULL,
  `deleted` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`role_id`),
  UNIQUE KEY `platform_role_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8;

